<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>Organizational Chart</title>
<style>
  body {
    margin: 0;
    padding: 40px 20px;
    background-color: #fff;
    display: flex;
    justify-content: center;
  }

  .org-chart {
    font-family: "Times New Roman", Times, serif;
    font-size: 13px;
    display: flex;
    flex-direction: column;
    align-items: center;
    width: 100%;
    max-width: 1400px;
  }

  .top-stub {
    width: 1px;
    height: 25px;
    background-color: black;
  }

  .columns-container {
    display: flex;
    width: 100%;
  }

  .column {
    display: flex;
    flex-direction: column;
    align-items: center;
    width: 20%;
    position: relative;
  }

  .connector-horizontal {
    position: absolute;
    top: 0;
    height: 1px;
    background-color: black;
  }

  .col-1 .connector-horizontal { width: 50%; right: 0; }
  .col-2 .connector-horizontal { width: 100%; left: 0; }
  .col-3 .connector-horizontal { width: 100%; left: 0; }
  .col-4 .connector-horizontal { width: 100%; left: 0; }
  .col-5 .connector-horizontal { width: 50%; left: 0; }

  .connector-vertical-top {
    width: 1px;
    height: 25px;
    background-color: black;
  }

  .box {
    border: 1px solid black;
    width: 92%;
    box-sizing: border-box;
    text-align: center;
    padding: 15px 10px;
    background-color: white;
  }

  .main-box {
    height: 160px;
    display: flex;
    flex-direction: column;
    justify-content: flex-start;
    padding-top: 25px;
  }

  .connector-vertical-middle {
    width: 1px;
    height: 35px;
    background-color: black;
  }

  .stack {
    width: 92%;
    border: 1px solid black;
    box-sizing: border-box;
  }

  .sub-box {
    border-bottom: 1px solid black;
    padding: 15px 10px;
    text-align: center;
    display: flex;
    flex-direction: column;
    justify-content: center;
    min-height: 90px;
  }

  .sub-box:last-child {
    border-bottom: none;
  }

  .title {
    text-transform: uppercase;
    margin-bottom: 12px;
    line-height: 1.3;
  }

  .person {
    margin-bottom: 8px;
    line-height: 1.2;
  }

  .person:last-child {
    margin-bottom: 0;
  }

  .list {
    text-align: left;
    display: inline-block;
    margin: 8px auto 0;
    line-height: 1.5;
  }
</style>
</head>
<body>

<div class="org-chart">
  <div class="top-stub"></div>
  <div class="columns-container">

    <!-- Column 1 -->
    <div class="column col-1">
      <div class="connector-horizontal"></div>
      <div class="connector-vertical-top"></div>
      <div class="box main-box">
        <div class="title">COMMISSION ON THE<br>PROFESSIONAL SOCIETY</div>
        <div class="person">Thomas H. Daniels<br>Chairman</div>
        <div class="person">Robert J. Boerema<br>Vice Chairman</div>
      </div>
      <div class="connector-vertical-middle"></div>
      <div class="stack">
        <div class="sub-box">
          <div class="title">COORDINATION</div>
          <div class="person">Richard E. Pryor<br>Chairman</div>
          <div class="list">
            <div>a. Chapter Affairs</div>
            <div>b. Student Affairs</div>
            <div>c. Membership</div>
          </div>
        </div>
        <div class="sub-box">
          <div class="title">RULES AND REGULATIONS</div>
          <div class="person">Jack West<br>Chairman</div>
          <div class="list">
            <div>a. Credentials Committee</div>
            <div>b. Resolutions Committee</div>
            <div>c. Nominating Committee</div>
          </div>
        </div>
        <div class="sub-box">
          <div class="title">HONORS AND AWARDS</div>
          <div class="person">John B. Marion<br>Chairman</div>
          <div class="list">
            <div>a. Craftsman Awards</div>
            <div>b. Student Awards</div>
            <div>c. Honor Awards</div>
          </div>
        </div>
        <div class="sub-box">
          <div class="title">REGIONAL JUDICIARY</div>
          <div class="person">Walter B. Schultz<br>Chairman</div>
        </div>
        <div class="sub-box">
          <div class="title">CONVENTION</div>
          <div class="person">Frank Folsom Smith<br>Chairman</div>
        </div>
      </div>
    </div>

    <!-- Column 2 -->
    <div class="column col-2">
      <div class="connector-horizontal"></div>
      <div class="connector-vertical-top"></div>
      <div class="box main-box">
        <div class="title">COMMISSION ON<br>EDUCATION AND<br>RESEARCH</div>
        <div class="person">James E. Garland<br>Chairman</div>
        <div class="person">John E. Sweet<br>Vice Chairman</div>
      </div>
      <div class="connector-vertical-middle"></div>
      <div class="stack">
        <div class="sub-box">
          <div class="title">TRAINING</div>
          <div class="person">John E. Sweet<br>Chairman</div>
        </div>
        <div class="sub-box">
          <div class="title">PROFESSIONAL<br>EDUCATION</div>
          <div class="person">James J. Jennewein<br>Chairman</div>
        </div>
        <div class="sub-box">
          <div class="title">RESEARCH AND<br>ARCHITECTURE</div>
          <div class="person">William G. Wagner<br>Chairman</div>
        </div>
      </div>
    </div>

    <!-- Column 3 -->
    <div class="column col-3">
      <div class="connector-horizontal"></div>
      <div class="connector-vertical-top"></div>
      <div class="box main-box">
        <div class="title">COMMISSION ON<br>PROFESSIONAL PRACTICE</div>
        <div class="person">Ivan H. Smith<br>Chairman</div>
        <div class="person">Charles E. Pattillo, III<br>Vice Chairman</div>
      </div>
      <div class="connector-vertical-middle"></div>
      <div class="stack">
        <div class="sub-box">
          <div class="title">PRACTICE<br>STANDARDS</div>
          <div class="person">Jack Moore<br>Chairman</div>
        </div>
        <div class="sub-box">
          <div class="title">PRACTICE AIDS</div>
          <div class="person">J. Arthur Wohlberg<br>Chairman</div>
        </div>
        <div class="sub-box">
          <div class="title">CONSTRUCTION<br>INDUSTRY</div>
          <div class="person">Roy M. Pooley, Jr.<br>Chairman</div>
        </div>
        <div class="sub-box">
          <div class="title">CONSULTANTS</div>
          <div class="person">Robert H. Levison, FAIA<br>Chairman</div>
        </div>
      </div>
    </div>

    <!-- Column 4 -->
    <div class="column col-4">
      <div class="connector-horizontal"></div>
      <div class="connector-vertical-top"></div>
      <div class="box main-box">
        <div class="title">COMMISSION ON<br>ARCHITECTURAL DESIGN</div>
        <div class="person">Paul Robin John<br>Chairman</div>
        <div class="person">Kenneth R. Miller<br>Vice Chairman</div>
      </div>
      <div class="connector-vertical-middle"></div>
      <div class="stack">
        <div class="sub-box">
          <div class="title">DESIGN</div>
          <div class="person">Paul Robin John<br>Chairman</div>
        </div>
        <div class="sub-box">
          <div class="title">PRESERVATION</div>
          <div class="person">F. Blair Reeves<br>Chairman</div>
        </div>
      </div>
    </div>

    <!-- Column 5 -->
    <div class="column col-5">
      <div class="connector-horizontal"></div>
      <div class="connector-vertical-top"></div>
      <div class="box main-box">
        <div class="title">COMMISSION ON<br>PUBLIC AFFAIRS</div>
        <div class="person">Arthur H. Rude<br>Chairman</div>
        <div class="person">John P. Stevens<br>Vice Chairman</div>
      </div>
      <div class="connector-vertical-middle"></div>
      <div class="stack">
        <div class="sub-box">
          <div class="title">PUBLIC RELATIONS</div>
          <div class="person">John R. Howey<br>Chairman</div>
        </div>
        <div class="sub-box">
          <div class="title">GOVERNMENT<br>AFFAIRS</div>
          <div class="person">Roy L. Ricks<br>Chairman</div>
        </div>
        <div class="sub-box">
          <div class="title">INTERNATIONAL<br>RELATIONS</div>
          <div class="person">Lemuel Ramos<br>Chairman</div>
        </div>
      </div>
    </div>

  </div>
</div>

</body>
</html>
```
